void dei_system_rf_keyboard_unlock( void )
{
  //if(  ss.locked     ) return ;
    if(  get_ss_lock() ) return ;//not available when the car is locked
	
	if( dei_feature_get( DEI_FEAT_RF_KEYBOARD_UNLOCK ) == 2 ) //feature is enable
	{		
		notify_send( NOTIFY_KEYBOARD_UNLOCK ) ; 				
	}
}

